/* Public pages and navigation; existing student tools keep their local data. */
const routePaths={landing:'/',home:'/student',profile:'/student/profile',quiz:'/student/assessment',grades:'/student/academics',majors:'/student/majors',schools:'/schools',simulate:'/student/simulate',report:'/student/report',example:'/example',login:'/login',register:'/register'};
const siteLocation=()=>window.MapleHosting?window.MapleHosting.route():location;const siteHistory=window.MapleHosting?window.MapleHosting.history:history;
const studentRenderer=render;
let previewIndex=0,schoolQuery='',schoolFocus='';
function routeFromLocation(){return Object.keys(routePaths).find(k=>routePaths[k]===siteLocation().pathname.replace(/\/$/,'')||routePaths[k]===siteLocation().pathname)||'notFound'}
function localSession(){try{return sessionStorage.getItem('maple-demo-session')==='1'}catch{return false}}
function navLink(key,text){return `<a href="${routePaths[key]}" ${page===key?'aria-current="page"':''}>${text}</a>`}
function togglePublicMenu(force){const menu=document.getElementById('public-main-nav'),button=document.getElementById('mobile-menu-toggle');if(!menu||!button)return;const open=typeof force==='boolean'?force:!menu.classList.contains('is-open');menu.classList.toggle('is-open',open);button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'关闭导航':'打开导航');button.textContent=open?'×':'☰'}
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.getElementById('public-main-nav')?.classList.contains('is-open')){togglePublicMenu(false);document.getElementById('mobile-menu-toggle')?.focus()}});
function publicHeader(){return `<div class="public-header"><a href="/" class="maple-brand">✳ <span>枫向 <small>MAPLEPATH</small></span></a><button id="mobile-menu-toggle" class="mobile-menu-toggle" aria-controls="public-main-nav" aria-expanded="false" aria-label="打开导航" onclick="togglePublicMenu()">☰</button><nav id="public-main-nav" aria-label="主导航">${navLink('landing','首页')}${navLink('schools','学校与专业')}<a href="/#how-it-works">如何使用</a>${navLink('example','示例报告')}</nav><div class="public-account">${localSession()?`<a href="/student" class="primary tiny">我的工作台 ↗</a><button class="link" onclick="exitDemo()">退出演示</button>`:`<a href="/login">登录</a><a href="/register" class="primary tiny">免费注册</a>`}</div></div>`}
function publicFooter(){return `<div class="public-footer"><div><b>✳ 枫向 MaplePath</b><p>认识自己，看见方向。</p></div><div><a href="/schools">学校探索</a><a href="/#how-it-works">使用流程</a><a href="/example">报告示例</a><a href="https://curriculum.gov.bc.ca/graduation" target="_blank" rel="noopener">BC课程官方资料 ↗</a></div><small>本地演示版 · 无云端账户及生成式AI · 不提供录取保证</small></div>`}
const previews=[['兴趣画像',`<span class="eyebrow">INTEREST PROFILE</span><h3>从喜欢投入的事情开始。</h3><div class="interest-chip">研究探索 I <b>较高偏好</b><div class="interest-track" aria-hidden="true"><span style="width:88%"></span></div></div><div class="interest-chip">实践动手 R <b>较高偏好</b><div class="interest-track" aria-hidden="true"><span style="width:76%"></span></div></div><p>小林喜欢研究问题和动手试验，可先体验工程与计算相关活动。</p><div class="note">兴趣是探索入口，不决定必须选择的专业。</div>`],['课程准备',`<span class="eyebrow">ACADEMIC SNAPSHOT</span><h3>把课程准备看清楚。</h3><div class="sample-row">English Studies 12 <b>在修 · 84%</b></div><div class="sample-row">Pre-Calculus 12 <b>在修 · 91%</b></div><div class="sample-row">Chemistry 12 <b>已完成 · 88%</b></div><div class="sample-row">Physics 12 <b class="warning">未录入</b></div><p>以下为虚构工程探索案例，不是某所大学的完整入学标准。</p>`],['关键差距',`<span class="eyebrow">KNOW YOUR NEXT STEP</span><h3>差距越具体，行动越清晰。</h3><div class="gap-callout"><span>01 · 课程待补充</span><b>Physics 12 尚未录入</b><p>先确认目标项目实际要求，再与辅导员讨论开课和先修关系。</p></div><p>英语能力、补充材料与具体项目规则仍需核实。</p>`],['行动建议',`<span class="eyebrow">YOUR ACTION PLAN</span><h3>用一次小行动验证方向。</h3><div class="sample-row">01 <span>确认目标入学项目与校区</span></div><div class="sample-row">02 <span>与辅导员核对Physics 12选课</span></div><div class="sample-row">03 <span>完成一个模型或编程小项目</span></div><div class="note">示例行动，不是对真实学生的个性化AI结论。</div>`],['情景对比',`<span class="eyebrow">EXPLORE WHAT CHANGES</span><h3>改变计划，看见变化。</h3><div class="compare-mini"><div>当前方案<strong>未录入</strong><small>Physics 12</small></div><span>→</span><div>改善方案<strong>计划修读</strong><small>仍待完成</small></div></div><p>添加计划课程后，缺失信息更明确，但不表示已经满足录取条件。</p>`]];
function previewMarkup(){return `<div class="preview-window"><div class="preview-top"><span>● ● ●</span> 小林的探索地图 <span class="pill">虚构示例</span></div><div role="tablist" aria-label="示例报告视图" class="preview-tabs">${previews.map((p,i)=>`<button id="preview-tab-${i}" role="tab" aria-selected="${i===previewIndex}" aria-controls="preview-panel" tabindex="${i===previewIndex?0:-1}" onclick="selectPreview(${i})" onkeydown="previewKey(event,${i})">${p[0]}</button>`).join('')}</div><div id="preview-panel" role="tabpanel" aria-labelledby="preview-tab-${previewIndex}" class="preview-panel">${previews[previewIndex][1]}</div><div class="preview-bottom">虚构示例，仅展示报告形式 · <a href="/example">查看完整示例 →</a></div></div>`}
function selectPreview(i,focus=false){previewIndex=i;$('#report-preview').innerHTML=previewMarkup();if(focus)$('#preview-tab-'+i).focus()}
function previewKey(e,i){let n=i;if(e.key==='ArrowRight')n=(i+1)%5;else if(e.key==='ArrowLeft')n=(i+4)%5;else if(e.key==='Home')n=0;else if(e.key==='End')n=4;else return;e.preventDefault();selectPreview(n,true)}
function landing(){return `<section class="landing-hero"><div><span class="eyebrow">BC CLASSROOM · CANADIAN POSSIBILITIES</span><h1>找到专业方向。<br><em>看清升学下一步。</em></h1><p class="landing-description">结合兴趣、课程成绩与个人经历。<br>探索专业选择、申请条件和准备路径。</p><ul class="value-list"><li>探索八所加拿大大学的本科路径</li><li>分开了解兴趣适配与课程准备</li><li>比较当前方案和改善后的变化</li></ul><div class="actions"><a href="/schools" class="primary">免费探索学校 →</a><a href="${localSession()?'/student':'/register'}" class="secondary">开始我的规划</a></div><small class="muted">学校介绍公开浏览 · 个人规划目前为本地演示</small></div><div id="report-preview">${previewMarkup()}</div></section><div class="pathway-strip" aria-label="探索入口"><a href="/schools"><strong>8</strong>所学校</a><a href="/register">专业探索 →</a><a href="/#how-it-works">BC 本科路径 →</a><a href="/example">示例报告 →</a></div><section class="public-section"><div class="section-title"><div><span class="eyebrow">EIGHT UNIVERSITIES, MORE POSSIBILITIES</span><h2>从你感兴趣的学校开始。</h2></div><a href="/schools">查看全部学校 ↗</a></div><div class="university-grid">${schools.map(s=>`<a class="university-tile" href="/schools?school=${encodeURIComponent(s[0])}"><div class="university-identity-top"><img class="university-crest" src="${schoolIdentity[s[0]].crest}" alt="${schoolIdentity[s[0]].fullName} 校徽" width="56" height="64" loading="lazy"><span class="pill">${s[2]}</span></div><b data-no-translate>${schoolIdentity[s[0]].short}</b><span class="university-fullname" data-no-translate>${schoolIdentity[s[0]].fullName}</span><small class="school-local-name">${s[1]}</small><i>↗</i></a>`).join('')}</div></section><section id="how-it-works" class="public-section"><span class="eyebrow">A CLEAR WAY FORWARD</span><h2>三个步骤，把可能变成下一步。</h2><div class="grid steps-grid">${[['01','认识自己','探索兴趣与学习偏好，用体验验证专业方向。'],['02','整理准备','记录课程、成绩与个人经历，形成自己的学习档案。'],['03','比较路径','选择目标项目，了解条件差距和可执行的行动。']].map(s=>`<article class="card"><span class="step-number">${s[0]}</span><h3>${s[1]}</h3><p>${s[2]}</p></article>`).join('')}</div></section><section class="public-section comparison-section"><div><span class="eyebrow">SMALL CHANGES, CLEARER PLANS</span><h2>先看清变化，<br>再决定如何行动。</h2><p>模拟改善方案，保留你的真实记录。<br>每个结论都应该说清依据与未知项。</p><a href="/example" class="link">阅读完整虚构示例 →</a></div><div class="card"><span class="badge">虚构工程探索案例</span><div class="comparison-table" role="table" aria-label="情景对比"><div role="row"><b role="columnheader">准备项</b><b role="columnheader">当前</b><b role="columnheader">改善计划</b></div><div role="row"><span role="cell">Physics 12</span><span role="cell">未录入</span><span role="cell">计划修读</span></div><div role="row"><span role="cell">数学成绩</span><span role="cell">在修91%</span><span role="cell">假设目标93%</span></div><div role="row"><span role="cell">项目完整要求</span><span role="cell">待核实</span><span role="cell">仍待核实</span></div></div><p>计划不等于完成，目标成绩不等于已取得成绩。</p></div></section><section class="public-section faq-section"><span class="eyebrow">A FEW THINGS TO KNOW</span><h2>开始前，你可能想了解。</h2>${[['哪些内容可以免费浏览？','学校目录、官方申请入口、使用流程与虚构报告示例均可公开浏览。'],['是否必须注册？','正式学生服务规划为注册后使用。当前版本还没有云端注册，可进入明确标记的本地演示工作台。'],['适用于哪些学生？','主要面向BC普通高中课程学生，包括中国国际学生和加拿大本地学生。其他课程体系需要单独核验。'],['会保证录取吗？','不会。规则示例用于理解准备条件，最终决定由大学作出；当前版本不提供录取概率。'],['专业测评决定我必须学什么吗？','不会。自编兴趣问卷用于探索，你可以结合课程体验和个人偏好重新考虑。'],['我的成绩与经历是否公开？','当前原型数据仅保存在此浏览器，不上传云端，也没有公开分享。共用设备可能访问这些本地数据；请勿录入敏感资料。']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><section class="closing-cta"><h2>你的方向，从一次探索开始。</h2><a href="/schools" class="primary">探索学校 →</a><a href="/example" class="secondary">先看示例报告</a></section>`}
home=function(){const next=!state.done?['quiz','完成兴趣探索','先从喜欢投入的活动认识自己。']:!state.courses.length?['grades','完善课程成绩','记录在修与已完成课程，让准备情况更清楚。']:['simulate','检查课程准备','用现有课程体验UBC工程条件检查示例。'];return title('YOUR LOCAL WORKSPACE','欢迎回到你的规划空间。','本地演示工作台 · 数据仅存于当前浏览器，尚未接入云端账户或AI。')+`<div class="next-action"><span class="eyebrow">YOUR NEXT STEP</span><h2>${next[1]}</h2><p>${next[2]}</p><button class="primary" onclick="go('${next[0]}')">继续准备 →</button></div><div class="metrics"><div class="metric"><span>兴趣探索</span><strong>${state.done?'已完成':filled()+' / 12'}</strong></div><div class="metric"><span>已记录课程</span><strong>${state.courses.length} 门</strong></div><div class="metric"><span>收藏专业方向</span><strong>${state.saved.length} 个</strong></div></div><div class="split"><section class="card"><h2>我的收藏方向</h2>${state.saved.length?majors.filter(m=>state.saved.includes(m.id)).map(m=>`<div class="list-item"><b>${m.name}</b><small>${m.en}</small></div>`).join(''):'<p>还没有收藏。先了解专业的学习内容，再选择值得体验的方向。</p>'}<button class="link" onclick="go('majors')">探索专业 →</button></section><section class="card"><h2>准备行动清单</h2><div class="list-item">${state.done?'✓':'○'} 完成兴趣探索</div><div class="list-item">${state.courses.length?'✓':'○'} 记录课程与成绩</div><div class="list-item">○ 核对目标项目的完整申请要求</div><p>当前版本不保存历史模拟报告。</p><button class="link" onclick="go('report')">查看当前探索摘要 →</button></section></div><div class="actions"><a href="/" class="secondary">返回首页</a><a href="/schools" class="secondary">浏览学校</a><a href="/example" class="secondary">查看独立示例</a></div>`};
function examplePage(){return title('A FICTIONAL STUDENT, A CLEARER PATH','先看看，一份规划可以告诉你什么。','虚构学生小林 · BC 11年级 · 工程探索案例，不代表任何大学完整招生要求。')+`<div class="split"><div id="report-preview">${previewMarkup()}</div><div class="card"><h2>把建议变成下一步</h2><div class="list-item"><b>确认具体目标</b><small>先选校区与入学项目，再核对官方条件。</small></div><div class="list-item"><b>补充课程计划</b><small>Physics 12未录入；先确认是否需要及何时能完成。</small></div><div class="list-item"><b>体验专业学习</b><small>用一次模型制作或编程项目验证兴趣。</small></div><div class="note">此页面使用独立固定示例，不读取或覆盖你的个人档案，不调用AI。</div><a href="/register" class="primary">了解如何开始 →</a></div></div>`}
function authNotice(){return `<section class="auth-notice card"><span class="eyebrow">MAPLEPATH · LOCAL PREVIEW</span><h1>${page==='register'?'开始你的升学规划':'进入规划空间'}</h1><span class="badge warn">云端注册与登录尚未接入</span><p>目前可以进入本地演示工作台，体验兴趣测评、成绩记录与情景模拟。这里不会创建真实账户，也不需要密码。</p><div class="note">请使用虚构资料。数据保存在此浏览器，共用设备上也可能被访问。</div><button class="primary" onclick="enterDemo()">进入本地演示 →</button><div class="actions"><a href="/schools">先浏览学校</a><a href="/example">查看示例报告</a></div></section>`}
function enterDemo(){try{sessionStorage.setItem('maple-demo-session','1')}catch{}const next=new URLSearchParams(siteLocation().search).get('next');go(Object.keys(routePaths).find(k=>routePaths[k]===next)||'home')}
function exitDemo(){try{sessionStorage.removeItem('maple-demo-session')}catch{}go('landing')}
function schoolSearch(){return title('CANADIAN UNIVERSITY PATHWAYS','探索加拿大大学。','八所学校的官方入口公开浏览。详细项目仍在整理，课程检查目前只提供UBC工程示例。')+`<div class="school-identification-note">学校标识仅用于资料识别，不表示合作或官方背书。</div><div class="school-search"><label for="school-search">搜索学校</label><input id="school-search" type="search" placeholder="输入中文或英文校名" value="${esc(schoolQuery)}" oninput="schoolQuery=this.value;schoolFocus='';updateSchoolResults()"><span id="school-count" class="muted"></span></div><div class="switches">${['全部','BC','ON','QC','AB'].map(s=>`<button class="${filter===s?'active':''}" aria-pressed="${filter===s}" onclick="filter='${s}';schoolFocus='';render()">${s}</button>`).join('')}</div><div id="school-results" class="public-schools"></div>`}
function updateSchoolResults(){const rawQuery=schoolQuery.trim().toLowerCase();const q=window.MapleLanguage?MapleLanguage.normalizeQuery(rawQuery):rawQuery;const list=schools.filter(s=>(filter==='全部'||s[2]===filter)&&(!schoolFocus||s[0]===schoolFocus)&&(!q||(s[0]+' '+s[1]+' '+schoolIdentity[s[0]].short+' '+schoolIdentity[s[0]].fullName).toLowerCase().includes(q)));$('#school-count').textContent=list.length+' 所学校';$('#school-results').innerHTML=list.length?list.map(s=>`<article class="card"><div class="school-art school-crest-art"><img src="${schoolIdentity[s[0]].crest}" alt="${schoolIdentity[s[0]].fullName} 校徽" width="110" height="130" loading="lazy"><span class="school-short" data-no-translate>${schoolIdentity[s[0]].short}</span><span class="pill">${s[2]}</span></div><h2 class="school-official-name" data-no-translate>${schoolIdentity[s[0]].fullName}</h2><p class="school-local-name">${s[1]}</p><p>${s[4]}</p><span class="badge ${s[0]==='UBC'?'':'warn'}">${s[0]==='UBC'?'工程：课程检查示例':'项目细则整理中'}</span><div class="actions school-links"><a href="${s[3]}" target="_blank" rel="noopener">官方申请要求 ↗</a><a href="${schoolIdentity[s[0]].source}" target="_blank" rel="noopener">校徽来源 ↗</a></div>${s[0]==='UBC'?`<div class="actions"><button class="primary tiny" onclick="go(localSession()?'simulate':'login')">体验工程准备检查</button></div>`:''}</article>`).join(''):`<div class="empty card"><h3>没有找到匹配的学校</h3><p>试试其他校名或清除筛选。</p><button class="secondary" onclick="schoolQuery='';schoolFocus='';filter='全部';render()">清除筛选</button></div>`}
go=function(p){const dest=routePaths[p]||'/';siteHistory.pushState({},'',dest);page=p;schoolFocus='';render();window.scrollTo(0,0)};
render=function(){const student=['home','profile','quiz','grades','majors','simulate','report'].includes(page);if(student&&!localSession()){const next=routePaths[page];siteHistory.replaceState({},'','/login?next='+encodeURIComponent(next));page='login';return render()}document.body.classList.toggle('public-site',!student);document.title=(page==='landing'?'枫向 MaplePath · 看见你的大学方向':(tabs.find(t=>t[0]===page)?.[2]||({example:'示例报告',login:'演示入口',register:'开始规划',schools:'学校探索'}[page]||'页面未找到'))+' · MaplePath');$('#public-nav').innerHTML=publicHeader();$('#public-footer').innerHTML=publicFooter();if(student){studentRenderer();$('#nav').insertAdjacentHTML('beforeend','<a class="sidebar-home" href="/">← 返回公开首页</a>')}else{$('#app').innerHTML=({landing,schools:schoolSearch,example:examplePage,login:authNotice,register:authNotice}[page]||(()=>title('404','这里还没有页面。','可以返回首页继续探索。')+'<a href="/" class="primary">返回首页</a>'))();if(page==='schools')updateSchoolResults()}if(siteLocation().hash==='#how-it-works')requestAnimationFrame(()=>document.getElementById('how-it-works')?.scrollIntoView())};
demo=function(){go('example')};
document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||a.target||a.hasAttribute('download'))return;const clicked=new URL(a.href,location.href);const u=window.MapleHosting?window.MapleHosting.decode(clicked):clicked;if(u.origin!==location.origin)return;e.preventDefault();siteHistory.pushState({},'',u.pathname+u.search+u.hash);page=routeFromLocation();schoolFocus=u.searchParams.get('school')||'';schoolQuery='';filter='全部';render();if(!u.hash)window.scrollTo(0,0)});
window.addEventListener('popstate',()=>{page=routeFromLocation();schoolFocus=new URLSearchParams(siteLocation().search).get('school')||'';render()});
page=routeFromLocation();schoolFocus=new URLSearchParams(siteLocation().search).get('school')||'';render();
